import 'package:flutter/material.dart';
import '../../../services/auth/auth_service.dart';
import '../../../services/personal_ai/daily_plan_service.dart';
class AurenDailyPlanScreen extends StatefulWidget{const AurenDailyPlanScreen({super.key});@override State<AurenDailyPlanScreen> createState()=>_AurenDailyPlanScreenState();}
class _AurenDailyPlanScreenState extends State<AurenDailyPlanScreen>{final _auth=FirebaseAurenAuthService();final _service=DailyPlanService();AurenDailyPlan? _plan;bool _loading=false;
Future<void> _build()async{final uid=_auth.currentUserId;if(uid==null)return;setState(()=>_loading=true);try{final p=await _service.build(uid);if(mounted)setState(()=>_plan=p);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر بناء خطة اليوم: $e')));}finally{if(mounted)setState(()=>_loading=false);}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Daily Plan')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('خطة اليوم مع AUREN',style:TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('خطة صغيرة مبنية على هدفك الحالي، بدون تحميل يومك أكثر من اللازم.'),const SizedBox(height:20),FilledButton.icon(onPressed:_loading?null:_build,icon:const Icon(Icons.today),label:Text(_loading?'جاري البناء…':'ابنِ خطة اليوم')),if(_plan!=null)...[const SizedBox(height:20),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(_plan!.goalTitle,style:const TextStyle(fontSize:19,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text(_plan!.focus),const SizedBox(height:14),..._plan!.steps.asMap().entries.map((entry)=>ListTile(contentPadding:EdgeInsets.zero,leading:CircleAvatar(radius:14,child:Text('${entry.key+1}')),title:Text(entry.value))) ])))]));}